  const hk_real t7 = HK_PI;
  const hk_real d7 = HK_LIT(0);
  const hk_real t8 = HK_LIT(2);
  const hk_real d8 = HK_LIT(0);
  const hk_real t9 = (t7 / t8);
  const hk_real d9 = ((d7 * t8 - t7 * d8) / (t8 * t8));
  const hk_real t10 = (t0 * t3);
  const hk_real d10 = (d0 * t3 + t0 * d3);
  const hk_real t11 = (t1 * t2);
  const hk_real d11 = (d1 * t2 + t1 * d2);
  const hk_real t12 = (t10 + t11);
  const hk_real d12 = (d10 + d11);
  const hk_real t13 = (t4 - t5);
  const hk_real d13 = (d4 - d5);
