  const hk_real d12 = HK_LIT(0);
  const hk_real t13 = (t0 / t12);
  const hk_real d13 = ((d0 * t12 - t0 * d12) / (t12 * t12));
  const hk_real t14 = HK_LIT(0);
  const hk_real d14 = HK_LIT(0);
