  const hk_real d21 = (d1 * t13 + t1 * d13);
  const hk_real t22 = (t13 * t1);
  const hk_real d22 = (d13 * t1 + t13 * d1);
  const hk_real t23 = (t21 - t22);
  const hk_real d23 = (d21 - d22);
