  hk_bx_mul(lo6, hi6, L6, lo7, hi7, L7, &lo8, &hi8, &L8);
  hk_real lo9, hi9, L9;
  hk_bx_neg(lo3, hi3, L3, &lo9, &hi9, &L9);
  hk_real lo10, hi10, L10;
  hk_bx_trig(1, lo4, hi4, L4, &lo10, &hi10, &L10);
  hk_real lo11, hi11, L11;
  hk_bx_mul(lo9, hi9, L9, lo10, hi10, L10, &lo11, &hi11, &L11);
  hk_real lo12, hi12, L12;
  hk_bx_add(lo8, hi8, L8, lo11, hi11, L11, &lo12, &hi12, &L12);
  hk_real lo13, hi13, L13;
  hk_bx_neg(lo6, hi6, L6, &lo13, &hi13, &L13);
  hk_real lo14, hi14, L14;
  hk_bx_mul(lo13, hi13, L13, lo10, hi10, L10, &lo14, &hi14, &L14);
  hk_real lo15, hi15, L15;
  hk_bx_mul(lo9, hi9, L9, lo7, hi7, L7, &lo15, &hi15, &L15);
  hk_real lo16, hi16, L16;
  hk_bx_add(lo14, hi14, L14, lo15, hi15, L15, &lo16, &hi16, &L16);
  hk_real lo17, hi17, L17;
  hk_bx_sub(lo12, hi12, L12, lo5, hi5, L5, &lo17, &hi17, &L17);
  hk_real lo18, hi18, L18;
  hk_bx_pow(lo17, hi17, L17, 2, &lo18, &hi18, &L18);
  hk_real lo19, hi19, L19;
  hk_bx_sub(lo16, hi16, L16, lo1, hi1, L1, &lo19, &hi19, &L19);
  hk_real lo20, hi20, L20;
  hk_bx_pow(lo19, hi19, L19, 2, &lo20, &hi20, &L20);
  hk_real lo21, hi21, L21;
  hk_bx_add(lo18, hi18, L18, lo20, hi20, L20, &lo21, &hi21, &L21);
  hk_real lo22, hi22, L22;
  hk_bx_sqrt(lo21, hi21, L21, &lo22, &hi22, &L22);
