  hk_real lo4, hi4, L4;
  hk_bx_mul(lo0, hi0, L0, lo3, hi3, L3, &lo4, &hi4, &L4);
  hk_real lo5, hi5, L5;
  hk_bx_mul(lo1, hi1, L1, lo2, hi2, L2, &lo5, &hi5, &L5);
  hk_real lo6, hi6, L6;
  hk_bx_sub(lo4, hi4, L4, lo5, hi5, L5, &lo6, &hi6, &L6);
  hk_real lo7, hi7, L7;
  hk_bx_sub(lo2, hi2, L2, lo0, hi0, L0, &lo7, &hi7, &L7);
  hk_real lo8, hi8, L8;
  hk_bx_pow(lo7, hi7, L7, 2, &lo8, &hi8, &L8);
  hk_real lo9, hi9, L9;
  hk_bx_sub(lo3, hi3, L3, lo1, hi1, L1, &lo9, &hi9, &L9);
  hk_real lo10, hi10, L10;
  hk_bx_pow(lo9, hi9, L9, 2, &lo10, &hi10, &L10);
  hk_real lo11, hi11, L11;
  hk_bx_add(lo8, hi8, L8, lo10, hi10, L10, &lo11, &hi11, &L11);
